CrosTelemetryAsyncWaiter::CrosTelemetryAsyncWaiter(
    CrosTelemetry* proxy) : proxy_(proxy) {}

CrosTelemetryAsyncWaiter::~CrosTelemetryAsyncWaiter() = default;

void CrosTelemetryAsyncWaiter::ProbeTelemetryInfo(
    const WTF::Vector<ProbeCategoryEnum>& categories, ProbeTelemetryInfoPtr* out_telemetry_info) {
  base::RunLoop loop;
  proxy_->ProbeTelemetryInfo(std::move(categories),
      base::BindOnce(
          [](base::RunLoop* loop,
             ProbeTelemetryInfoPtr* out_telemetry_info
,
             ProbeTelemetryInfoPtr telemetry_info) {*out_telemetry_info = std::move(telemetry_info);
            loop->Quit();
          },
          &loop,
          out_telemetry_info));
  loop.Run();
}

ProbeTelemetryInfoPtr CrosTelemetryAsyncWaiter::ProbeTelemetryInfo(
    const WTF::Vector<ProbeCategoryEnum>& categories) {
  ProbeTelemetryInfoPtr async_wait_result;
  ProbeTelemetryInfo(std::move(categories),&async_wait_result);
  return async_wait_result;
}






